 IF NOT ((SELECT COUNT(*) FROM zone_points WHERE `id` <=> 1732 AND BINARY `zone` <=> BINARY CONVERT(0x6f6c64626c61636b627572726f77 USING utf8mb4) AND `version` <=> 0 AND `number` <=> 10 AND CAST(`y` AS DOUBLE) <=> CAST(0.0 AS DOUBLE) AND CAST(`x` AS DOUBLE) <=> CAST(0.0 AS DOUBLE) AND CAST(`z` AS DOUBLE) <=> CAST(0.0 AS DOUBLE) AND CAST(`heading` AS DOUBLE) <=> CAST(0.0 AS DOUBLE) AND CAST(`target_y` AS DOUBLE) <=> CAST(3414.0 AS DOUBLE) AND CAST(`target_x` AS DOUBLE) <=> CAST(-996.0 AS DOUBLE) AND CAST(`target_z` AS DOUBLE) <=> CAST(8.0 AS DOUBLE) AND CAST(`target_heading` AS DOUBLE) <=> CAST(999.0 AS DOUBLE) AND `zoneinst` <=> 0 AND `target_zone_id` <=> 466 AND `target_instance` <=> 0 AND CAST(`buffer` AS DOUBLE) <=> CAST(0.0 AS DOUBLE) AND `client_version_mask` <=> 4294967295 AND `min_expansion` <=> -1 AND `max_expansion` <=> -1 AND `content_flags` <=> NULL AND `content_flags_disabled` <=> NULL AND `is_virtual` <=> 0 AND `height` <=> 0 AND `width` <=> 0)=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Original exit zone point differs'; END IF;
 IF NOT (NOT EXISTS(SELECT 1 FROM zone_points WHERE zone='oldblackburrow' AND number=10 AND version IN(-1,1,2))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Exit mapping version namespace occupied'; END IF;
 IF NOT ((SELECT COUNT(*) FROM zone WHERE `id` <=> 396 AND `zoneidnumber` <=> 459 AND `version` <=> 0 AND `min_status` <=> 80)=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='First slice zone access preimage differs'; END IF;
 IF NOT ((SELECT COUNT(*) FROM zone WHERE `id` <=> 397 AND `zoneidnumber` <=> 460 AND `version` <=> 0 AND `min_status` <=> 80)=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='First slice zone access preimage differs'; END IF;
 IF NOT ((SELECT COUNT(*) FROM zone WHERE `id` <=> 260 AND `zoneidnumber` <=> 466 AND `version` <=> 0 AND `min_status` <=> 80)=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='First slice zone access preimage differs'; END IF;
 IF NOT ((SELECT COUNT(*) FROM zone WHERE `id` <=> 261 AND `zoneidnumber` <=> 467 AND `version` <=> 0 AND `min_status` <=> 80)=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='First slice zone access preimage differs'; END IF;
 IF NOT ((SELECT COUNT(*) FROM zone WHERE `id` <=> 264 AND `zoneidnumber` <=> 468 AND `version` <=> 0 AND `min_status` <=> 80)=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='First slice zone access preimage differs'; END IF;

-- Preconditions complete; schema operations below may commit individually.
-- OWNER-REVIEW SOURCE ONLY. Database owner applies after guarded schema/preimage
-- review; never run a fresh-install export over player data. Both tables must
-- reside beside native character/shared history on the character DB, InnoDB.
CREATE TABLE sod_task_reward_quotes (
 task_id INT UNSIGNED NOT NULL,
 occurrence_kind TINYINT UNSIGNED NOT NULL COMMENT '0=native personal occurrence; 1=canonical shared run',
 occurrence_id BIGINT UNSIGNED NOT NULL,
 accepted_at INT UNSIGNED NOT NULL,
 model_version INT UNSIGNED NOT NULL,
 popularity_count BIGINT UNSIGNED NOT NULL,
 amount INT UNSIGNED NOT NULL,
 PRIMARY KEY(task_id,occurrence_kind,occurrence_id)
) ENGINE=InnoDB;
CREATE TABLE sod_task_popularity_events (
 task_id INT UNSIGNED NOT NULL,
 occurrence_kind TINYINT UNSIGNED NOT NULL,
 occurrence_id BIGINT UNSIGNED NOT NULL,
 completed_at INT UNSIGNED NOT NULL,
 PRIMARY KEY(task_id,occurrence_kind,occurrence_id),
 KEY task_window(task_id,completed_at)
) ENGINE=InnoDB;
-- Minimal mission controller journal, not a completion/entitlement flag.
-- Native history/archive remains sole progression authority.
CREATE TABLE sod_task_scene_runs (
 shared_task_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
 task_id INT UNSIGNED NOT NULL,
 instance_id INT UNSIGNED NOT NULL,
 model_version INT UNSIGNED NOT NULL,
 state TINYINT UNSIGNED NOT NULL DEFAULT 0,
 started_at INT UNSIGNED NOT NULL DEFAULT 0,
 seed CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 updated_at INT UNSIGNED NOT NULL
) ENGINE=InnoDB;

-- Frozen native level-based EXP input per existing provider occurrence.
CREATE TABLE sod_task_recipient_reward_inputs (
 character_id INT UNSIGNED NOT NULL,
 task_id INT UNSIGNED NOT NULL,
 occurrence_id BIGINT UNSIGNED NOT NULL,
 experience_amount BIGINT UNSIGNED NOT NULL,
 PRIMARY KEY(character_id,task_id,occurrence_id)
) ENGINE=InnoDB;
-- Early Chief-key action receipt, scoped to native run; existing inventory writer
-- remains owner. Status0 after an interrupted write is quarantined, never replayed.
CREATE TABLE sod_task_scene_actions (
 shared_task_id BIGINT UNSIGNED NOT NULL,
 action_id TINYINT UNSIGNED NOT NULL,
 character_id INT UNSIGNED NOT NULL,
 item_id INT UNSIGNED NOT NULL,
 status TINYINT UNSIGNED NOT NULL,
 updated_at INT UNSIGNED NOT NULL,
 PRIMARY KEY(shared_task_id,action_id)
) ENGINE=InnoDB;
CREATE TABLE sod_task_ward_uses (
 shared_task_id BIGINT UNSIGNED NOT NULL,
 character_id INT UNSIGNED NOT NULL,
 used_at BIGINT UNSIGNED NOT NULL COMMENT 'native server milliseconds',
 PRIMARY KEY(shared_task_id,character_id)
) ENGINE=InnoDB;

-- CONTENT DATABASE, owner review/apply only; bindings from numeric reservations.
-- NO zero/default numeric IDs. Not an entitlement or character state table.
CREATE TABLE sod_scene_actor_bindings (
 task_id INT UNSIGNED NOT NULL,
 role VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 npc_type_id INT UNSIGNED NOT NULL,
 PRIMARY KEY(task_id,role)
) ENGINE=InnoDB;

